(()=>{'use strict';
const{World,COLORS,RECIPES,TRAITS}=SocietyNext,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>Math.round(n*100)/100,clock=n=>`${Math.floor(n/60)}h ${n%60}m`;
let world=SocietySession.load(),selected=new URLSearchParams(location.search).get('agent')||'a0',tab='story',layer='social',playing=false,last=performance.now(),elapsed=0,lastRender=0,worker=null,results=null,storage=true;
const drawPositions={};
const embedded=new URLSearchParams(location.search).has('embedded');if(embedded)document.body.classList.add('embedded');
const points={common:[17,28],garden:[43,72],textiles:[62,32],dyes:[64,60],pond:[16,76],grove:[83,30],quarry:[84,78]},labels={common:'Common',garden:'Garden',textiles:'Textiles',dyes:'Dyes',pond:'Pond',grove:'Grove',quarry:'Quarry'};
const names=id=>world.agent(id)?.name||id;const colors=id=>COLORS[Number(id.replace(/\D/g,''))%COLORS.length];
function table(head,rows){return`<div class="scroll-table"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function save(){storage=SocietySession.save(world)}function pause(){playing=false;$('#run').textContent='Run'}
function download(file,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=file;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function select(id){if(!world.agent(id))return;selected=id;render()}
$('#run').onclick=()=>{playing=!playing;$('#run').textContent=playing?'Pause':'Run'};
$('#step').onclick=()=>{pause();world.advance(1);world.validate();save();render()};$('#hour').onclick=()=>{pause();world.advance(60);world.validate();save();render()};
$('#export').onclick=()=>download(`society-v2-${world.s.initialSeed}-${world.s.time}.json`,world.snapshot());
$('#reset').onclick=()=>{pause();$('#reset-dialog').showModal()};$('#cancel-reset').onclick=()=>$('#reset-dialog').close();
$('#new-world').onsubmit=e=>{e.preventDefault();try{localStorage.setItem(SocietySession.KEY+'-previous',JSON.stringify(world.snapshot()))}catch{}world=new World({seed:Number($('#seed').value),count:Number($('#count').value),scarcity:$('#scarcity').checked,socialFashion:$('#fashion').checked,oracle:$('#oracle').checked,groups:$('#groups').checked,coordination:$('#coordination').checked});selected='a0';save();$('#reset-dialog').close();render()};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});
function inspector(a){const h=world.currentHat(a),summary=world.summary(a);$('#inspector').innerHTML=`<h2>${esc(a.name)}</h2><span class="fine">${esc(labels[a.hub])} · ${esc(a.action?.type||'deciding')}</span><div class="next-why">${esc(summary.reason)}</div><div class="need-strip">${['hunger','fatigue','loneliness'].map(k=>`<label>${k}<meter min="0" max="100" value="${a.needs[k]}">${Math.round(a.needs[k])}</meter></label>`).join('')}</div><p>${h?`<span class="hat-swatch" style="--hat:${h.color}"></span>Wearing ${h.color}`:'No hat yet.'}</p><p class="fine">${num(a.inventory.food)} food · reserve ${num(world.reserve(a))}<br>${esc(summary.friend)}<br>${esc(summary.conflict)}</p><details><summary>Personality, knowledge & obligations</summary><p>${Object.entries(a.traits).map(([k,v])=>`<abbr title="${esc(TRAITS[k])}">${k}</abbr> ${v}`).join(' · ')}</p><p>Preferred color <span class="dot" style="background:${a.taste}"></span>${a.taste}. Processes known: ${a.known.map(esc).join(', ')}.</p><p>${esc(summary.obligations)}</p><p>Memberships: ${summary.groups.map(g=>esc(g.kind)).join(', ')||'none yet'}.</p><p>Inventory: ${Object.entries(a.inventory).filter(([,v])=>v>0).map(([k,v])=>`${num(v)} ${k}`).join(' · ')}.</p><p>No generic interests or skill bars. Mediation reputation comes from experiences.</p></details>`}
function map(a){const grouped={};for(const b of world.s.agents)(grouped[b.hub]||=[]).push(b);$('#map-labels').innerHTML=Object.entries(points).map(([hub,[x,y]])=>`<span class="hub" style="left:${x}%;top:${y-13}%">${labels[hub]}</span>`).join('');$('#cast').innerHTML=world.s.agents.map(b=>{const h=world.currentHat(b);return`<button class="button ${b.id===selected?'primary':''}" data-agent="${b.id}">${h?`<span class="dot" style="background:${h.color}"></span>`:''}${esc(b.name)}</button>`}).join('');$('#cast').querySelectorAll('[data-agent]').forEach(b=>b.onclick=()=>select(b.dataset.agent));}
function render(){const a=world.agent(selected)||world.s.agents[0];selected=a.id;const m=world.metrics();$('#clock').textContent=clock(world.s.time);$('#status').textContent=storage?'Saved in this browser. Tick = one simulated minute. No server runs while the browser is closed.':'Local saving failed; export your world before closing.';$('#stats').innerHTML=[['Food pressure',m.hunger>60?'High':m.hunger>30?'Moderate':'Low'],['Completed trades',m.trades],['Hats worn',`${m.hatOwners} / ${m.population}`],['Standing groups',m.groups]].map(([k,v])=>`<div>${k}<strong>${v}</strong></div>`).join('');document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('primary',b.dataset.tab===tab));map(a);inspector(a);renderView(a);const o=world.s.options;$('#seed').value=world.s.initialSeed;$('#count').value=o.count;for(const[id,key]of[['scarcity','scarcity'],['fashion','socialFashion'],['oracle','oracle'],['groups','groups'],['coordination','coordination']])$('#'+id).checked=o[key]}
function trend(){const h=world.s.history;if(h.length<2)return'';return`<svg class="next-trend" viewBox="0 0 600 130" role="img" aria-label="Average hunger over time, zero to one hundred"><path d="M20 15V105H580" fill="none" stroke="#a3b596"/><polyline points="${h.map((m,i)=>`${20+i*560/(h.length-1)},${105-m.hunger*.85}`).join(' ')}" fill="none" stroke="#ac7445" stroke-width="2"/><text x="25" y="15">Average hunger (0–100)</text><text x="20" y="122">${clock(h[0].minute)}</text><text x="510" y="122">${clock(h.at(-1).minute)}</text></svg>`}
function eventsHTML(events){return events.length?`<ol class="next-story">${events.slice().reverse().map(e=>`<li><time>${clock(e.time)} · ${esc(e.type)}</time>${esc(e.text)}</li>`).join('')}</ol>`:'<p class="next-empty">Nothing of this kind has happened yet. Advance time to observe decisions; outcomes are not preassigned.</p>'}
function network(a){const graph=world.graph(a,layer),positions={};positions[a.id]=[280,150];const others=graph.nodes.filter(n=>n.id!==a.id);others.forEach((n,i)=>{const angle=i/Math.max(1,others.length)*Math.PI*2-Math.PI/2;positions[n.id]=[280+210*Math.cos(angle),150+110*Math.sin(angle)]});return`<svg class="next-network" viewBox="0 0 560 300" role="group" aria-label="${esc(layer)} connections of ${esc(a.name)}"><defs><marker id="end" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0L7 3.5L0 7" fill="#687958"/></marker></defs>${graph.edges.map(e=>{const[x,y]=positions[e.from],[u,v]=positions[e.to],dx=u-x,dy=v-y,d=Math.hypot(dx,dy)||1;return`<g><title>${esc(e.label)}</title><line x1="${x+dx/d*23}" y1="${y+dy/d*23}" x2="${u-dx/d*25}" y2="${v-dy/d*25}" stroke="${e.kind==='tension'?'#b36745':layer==='economic'?'#527f9a':'#739453'}" stroke-width="${Math.min(5,1+e.value/30)}" marker-end="url(#end)"/><text x="${(x+u)/2}" y="${(y+v)/2+8}" text-anchor="middle">${esc(layer==='social'?e.kind:e.label)}</text></g>`}).join('')}${graph.nodes.map(n=>{const[x,y]=positions[n.id];return`<g ${n.type==='creature'?`data-agent="${n.id}"`:`data-group="${n.id}"`} role="button" tabindex="0" aria-label="Inspect ${esc(n.name)}"><circle cx="${x}" cy="${y}" r="${n.id===a.id?26:21}" fill="${n.type==='group'?'#e9d399':n.id===a.id?'#c6dc9b':'#e8efda'}" stroke="#31516c"/><text x="${x}" y="${y+4}" text-anchor="middle">${esc(n.type==='creature'?n.name.slice(0,2):'G')}</text><text x="${x}" y="${y+39}" text-anchor="middle">${esc(n.name)}</text></g>`}).join('')}</svg>${graph.edges.length?'':'<p class="fine">No recorded connections in this layer yet.</p>'}`}
function renderView(a){const v=$('#view');if(tab==='story'){const important=world.s.events.filter(e=>['group','supply','exit','breach','settlement','insight','advice','distribution','theft'].includes(e.type));v.innerHTML=`<div class="next-two"><section><h2>What changed?</h2><p class="fine">The latest consequential events. These are generated from this run, not scripted stories.</p>${eventsHTML(important.slice(-6))}</section><section><h2>Why ${esc(a.name)} did that</h2><p>${esc(a.reason)}</p>${trend()}<details><summary>Compare the choices underneath</summary>${table(['Option','Score','Why'],a.lastDecision.map(c=>`<tr><td>${esc(c.type)}${c.recipe?' '+esc(c.recipe):''}</td><td>${num(c.score)}</td><td>${esc(c.reason)}<small>${Object.entries(c.parts).map(([k,v])=>`${k}: ${num(v)}`).join(' · ')}</small></td></tr>`))}</details><details><summary>Recent events involving ${esc(a.name)}</summary>${eventsHTML(world.s.events.filter(e=>e.actors.includes(a.id)).slice(-8))}</details></section></div>`}
 if(tab==='people'){v.innerHTML=`<h2>${esc(a.name)}’s connections</h2><p class="fine">One person can like someone, distrust their deliveries, and still depend on their workshop. Switch layers to separate those connections. Only the strongest six social connections are drawn.</p><div class="next-filters">${[['social','People'],['economic','Trade & obligations'],['groups','Groups']].map(([id,n])=>`<button class="button ${layer===id?'primary':''}" data-layer="${id}">${n}</button>`).join('')}</div>${network(a)}<div class="next-legend"><span><i style="background:#739453"></i>Affection / membership</span><span><i style="background:#b36745"></i>Grievance</span><span><i style="background:#527f9a"></i>Economic connection</span></div><div class="next-two"><section><h3>Standing arrangements</h3>${world.memberships(a).map(g=>groupHTML(g)).join('')||'<p class="next-empty">No group membership yet. Social circles and workshops can overlap.</p>'}</section><section><h3>What ${esc(a.name)} believes</h3><p class="fine">Memories distinguish firsthand evidence from gossip. Trust is separate for social, economic and mediation experiences.</p>${table(['About','Experience','Source'],a.memories.slice(-5).reverse().map(m=>`<tr><td>${esc(names(m.subject))}</td><td>${esc(m.domain)} · ${m.outcome>0?'positive':'negative'}<br>${Math.round(m.confidence*100)}% confidence</td><td>${m.firsthand?'Firsthand':esc(names(m.source))}</td></tr>`))}<details><summary>Directional relationship values</summary>${table(['Person','Affection','Grievance','Trust: trade / social / mediation'],world.s.agents.filter(b=>b!==a&&world.s.edges[a.id+'>'+b.id]).map(b=>{const r=world.relation(a,b,false);return`<tr><td>${esc(b.name)}</td><td>${num(r.affection)}</td><td>${num(r.grievance)}</td><td>${['economic','social','mediation'].map(d=>Math.round(world.trust(a,b,d)*100)+'%').join(' / ')}</td></tr>`}))}</details></section></div>`;v.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{layer=b.dataset.layer;renderView(a)});v.querySelectorAll('[data-agent]').forEach(b=>{b.onclick=()=>select(b.dataset.agent);b.onkeydown=e=>{if(e.key==='Enter')select(b.dataset.agent)}});v.querySelectorAll('[data-group]').forEach(b=>{b.onclick=()=>document.getElementById(b.dataset.group)?.scrollIntoView({block:'center',behavior:'smooth'});b.onkeydown=e=>{if(e.key==='Enter')b.onclick()}})}
 if(tab==='economy'){const m=world.metrics(),recent=world.s.transactions.slice(-8).reverse(),total=(k)=>num(world.s.agents.reduce((s,a)=>s+a.inventory[k],0));v.innerHTML=`<h2>From materials to something people want</h2><p class="fine">Food sustains life. Hats express taste and belonging. Tools and workshops support production. Standard labor anchors asking prices; actual exchanges can depart from it.</p><div class="next-flow"><div><strong>Resources</strong>Fibre, pigment, water<br>Common sources</div><span class="arrow">→</span><div><strong>Cloth + dye</strong>${total('cloth')} cloth · ${total('dye')} dye<br>${m.inputTrades} input trades</div><span class="arrow">→</span><div><strong>Colored hats</strong>${m.hatsMade} made · ${m.hatTrades} sold<br>${m.hatOwners} creatures wearing one</div></div><div class="next-two"><section><h3>Who wants which color?</h3><p class="fine">Public requests are visible to ordinary producers. Hidden latent demand is available only through the optional insight experiment.</p>${world.s.agents.filter(b=>b.request).slice(0,6).map(b=>`<p><span class="dot" style="background:${b.request.color}"></span><strong>${esc(b.name)}</strong> is looking around ${b.request.color}.</p>`).join('')||'<p>No current public requests. Satisfaction or low resources can reduce demand.</p>'}<details><summary>${esc(a.name)}’s color preferences</summary>${table(['Color','Taste','Distinctiveness / familiarity','Belonging','Total appeal'],COLORS.map(color=>{const p=world.appeal(a,color);return`<tr><td><span class="dot" style="background:${color}"></span>${color}</td><td>${p.taste}</td><td>${p.novelty}</td><td>${p.belonging}</td><td>${p.total}</td></tr>`}))}</details></section><section><h3>Who controls production access?</h3>${world.s.assets.map(asset=>`<div class="next-group"><strong>${esc(asset.name)}</strong><br>${asset.slots} production slot(s) · ${num(asset.treasury)} food pooled<div class="shares">${Object.entries(asset.shares).map(([id,share])=>`<span style="--share:${share*100}%;--color:${id==='community'?'#9dbb73':colors(id)}" title="${esc(names(id))}: ${Math.round(share*100)}%"></span>`).join('')}</div>${Object.entries(asset.shares).map(([id,share])=>`${id==='community'?'Common access':esc(names(id))} ${Math.round(share*100)}%`).join(' · ')}</div>`).join('')}</section></div><h3>Recent exchanges</h3>${table(['Flow','Good','Food paid','Labor: good / payment'],recent.map(t=>`<tr><td>${esc(names(t.seller))} → ${esc(names(t.buyer))}</td><td>${t.color?`<span class="dot" style="background:${t.color}"></span>`:''}${esc(t.good)}</td><td>${t.food}</td><td>${t.referenceLabor} / ${t.paymentLabor} min</td></tr>`))}<details><summary>Supply contracts & ownership rules</summary>${table(['Agreement','Terms','State'],world.s.contracts.filter(c=>['supply','loan'].includes(c.kind)).slice(-15).reverse().map(c=>`<tr><td>${esc(names(c.from))} ↔ ${esc(names(c.to))}</td><td>${esc(c.kind)} · ${esc(c.terms.good||'food')}<br>${c.terms.price??c.terms.repayment??''} food</td><td>${esc(c.status)}</td></tr>`))}<p>Workshop shares grant reserved member access and equal proportional distributions. Construction requires timber, food and time. Exit pays the agreed treasury share and redistributes the departing ownership share. Land markets, wages, rent, revolts and governments are not implemented.</p></details>`}
 if(tab==='experiments')renderExperiments();}
function groupHTML(g){return`<div class="next-group" id="${g.id}"><strong>${esc(g.kind)} · ${g.id}</strong><br>${g.members.map(id=>esc(names(id))).join(', ')}<br>Coordinator: ${esc(names(g.coordinator))}<details><summary>Agreement</summary><p>${esc(g.purpose||g.access||'Shared production access')}.</p><p>${esc(g.distribution||'')}${g.good?' Coordinated asking prices for '+esc(g.good)+'.':''}</p><p>One member, one vote. Membership does not imply friendship.</p></details></div>`}
function renderExperiments(){const v=$('#view');v.innerHTML=`<h2>Which rules actually make a difference?</h2><p class="fine">Compare the same initial residents across taste-only demand, social fashion, no groups, no price coordination, hidden market insight, and food shortage. Four seeds × six approaches × one simulated day. Runs happen in a background worker and never replace your world.</p><button class="button primary" id="batch-run" ${worker?'disabled':''}>Run 24 comparisons</button> <button class="button" id="batch-cancel" ${worker?'':'disabled'}>Cancel</button> <span id="progress" role="status">${worker?'Running…':'Ready'}</span><div id="results">${results?resultsHTML(results):'<p class="next-empty">Run comparisons here, or read <a href="findings.html">the saved experiment findings</a>.</p>'}</div><details><summary>What is—and isn’t—emergent?</summary><p>Participants, trading partners, disputes, color choices and exits vary with decisions. Group charters, available actions and price-pact proposals are authored rules. A price pact is not evidence of a powerful cartel; no historical stage or ideology is assigned.</p><p>No interests or mediation skill. No LLM or vector database. Insight reads hidden current demand; it does not predict scheduled events. This is a local experimental simulation, not a persistent multiplayer service.</p></details><p><a href="lab-classic.html">Open the preserved classic laboratory</a> · <a href="society-next-experiments.json" download>Download recorded comparisons</a></p>`;
 $('#batch-run').onclick=()=>{pause();worker=new Worker('society-next-worker.js');$('#batch-run').disabled=true;$('#batch-cancel').disabled=false;worker.onmessage=e=>{const d=e.data;if(d.type==='progress'){$('#progress')&&($('#progress').textContent=`${d.done} / ${d.total}`)}else{worker.terminate();worker=null;if(d.type==='complete'){results=d.result;if(tab==='experiments')renderExperiments()}else if($('#progress')){$('#progress').textContent='Experiment failed: '+d.message;$('#batch-run').disabled=false;$('#batch-cancel').disabled=true}}};worker.onerror=e=>{worker?.terminate();worker=null;if($('#progress')){$('#progress').textContent='Worker failed: '+e.message;$('#batch-run').disabled=false;$('#batch-cancel').disabled=true}};worker.postMessage({});};$('#batch-cancel').onclick=()=>{worker?.terminate();worker=null;renderExperiments()};$('#download-results')?.addEventListener('click',()=>download('society-comparisons.json',results))}
function resultsHTML(result){const keys=['hatTrades','inputTrades','hunger','workshops','suppliesCreated','exits','revelations'];return`${table(['Approach','Hat sales','Input trades','Hunger','Workshops','Supply agreements created','Exits','Insights'],result.summary.map(r=>`<tr><td>${esc(r.name)}</td>${keys.map(k=>`<td>${num(r.mean[k])}</td>`).join('')}</tr>`))}<p class="fine">Means across ${result.seeds.length} seeds. Open the saved findings for ranges, limitations and individual events. These runs test authored game rules, not claims about actual societies.</p><button class="button" id="download-results">Export results</button>`}
function draw(now){const canvas=$('#world-canvas'),rect=canvas.getBoundingClientRect();if(!rect.width)return;const ratio=window.devicePixelRatio||1;if(canvas.width!==Math.round(rect.width*ratio)){canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio)}const c=canvas.getContext('2d');c.setTransform(ratio,0,0,ratio,0,0);c.clearRect(0,0,rect.width,rect.height);const grouped={};for(const a of world.s.agents)(grouped[a.hub]||=[]).push(a);const poses={work:'work',gather:'gather',social:'offer',listen:'receive',rest:'sit / rest',build:'work',trade:'carry',attune:'idle'};for(const a of world.s.agents){const[x,y]=points[a.hub],i=grouped[a.hub].indexOf(a),angle=i*2.4,offset=grouped[a.hub].length>1?14+Math.sqrt(i)*13:0,px=x/100*rect.width+Math.cos(angle)*offset,py=y/100*rect.height+Math.sin(angle)*offset;drawPositions[a.id]={x:px,y:py};const height=Math.max(28,Math.min(58,rect.height*.18));if(CreatureArt.ready)CreatureArt.sprite(c,a.kind,px,py,height,poses[a.action?.type]||'idle',now/1000);else{c.fillStyle='#d6e8bd';c.beginPath();c.arc(px,py-10,12,0,Math.PI*2);c.fill()}const h=world.currentHat(a);if(h){c.fillStyle=h.color;c.strokeStyle='#25394a';c.lineWidth=1;c.beginPath();c.moveTo(px-9,py-height);c.lineTo(px-6,py-height-10);c.lineTo(px+6,py-height-10);c.lineTo(px+9,py-height);c.closePath();c.fill();c.stroke();c.fillRect(px-12,py-height,24,3)}if(a.id===selected){c.strokeStyle='#d19927';c.lineWidth=2;c.beginPath();c.ellipse(px,py+3,18,5,0,0,Math.PI*2);c.stroke()}c.font='11px system-ui';c.textAlign='center';c.fillStyle='#17334b';c.fillText(a.name,px,py+18)}}
$('#world-canvas').onclick=e=>{const rect=e.target.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;const a=world.s.agents.filter(a=>drawPositions[a.id]).sort((a,b)=>Math.hypot(drawPositions[a.id].x-x,drawPositions[a.id].y-y)-Math.hypot(drawPositions[b.id].x-x,drawPositions[b.id].y-y))[0];if(a&&Math.hypot(drawPositions[a.id].x-x,drawPositions[a.id].y-y)<50)select(a.id)};
function frame(now){const dt=Math.min(250,now-last);last=now;if(playing&&!document.hidden){elapsed+=dt*Number($('#speed').value)/1000;const n=Math.min(10,Math.floor(elapsed));if(n){world.advance(n);elapsed-=n;if(now-lastRender>700){world.validate();save();render();lastRender=now}}}draw(now);requestAnimationFrame(frame)}
window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden)save()});fetch('society-next-experiments.json').then(r=>r.ok?r.json():null).then(r=>{if(r){results=r;if(tab==='experiments')renderExperiments()}}).catch(()=>{});render();save();requestAnimationFrame(frame);
})();
